const MET={people:['People',c=>nf(c.people)],reached:['Reached',c=>nf(c.reached)],replied:['Replied',c=>nf(c.replied)],interested:['Interested',c=>nf(c.interested)],booked:['Booked',c=>nf(c.booked)],installed:['Revenue stage',c=>nf(c.installed)],revenue:['Revenue',c=>c.revenue?money(c.revenue):'—'],cost:['Cost',c=>money(c.cost)],cpb:['Cost per booking',c=>c.booked?money(c.cost/c.booked,2):'—'],rr:['Reply rate',c=>c.reached?pct(c.replied/c.reached*100):'—'],conv:['Conversion',c=>c.reached?pct(c.installed/c.reached*100):'—']};
function stageCount(c,n){const L=stagesOf(c);const i=L.findIndex(s=>s.n===n);if(i<0)return 0;const s=L[i];if(s.rev)return c.installed;if(/Booked/.test(n))return c.booked;if(/Interested|Qualified/.test(n))return c.interested;if(/Contacted/.test(n))return Math.max(0,c.reached-c.replied);if(i===0)return Math.max(0,c.people-c.reached);if(s.t==='lost')return Math.round(c.replied*.18);if(s.t==='pending')return Math.round(c.replied*.12);return Math.round(c.booked*.7)}
function metVal(c,k){if(k.startsWith('st:'))return nf(stageCount(c,k.slice(3)));return MET[k][1](c)}
function metLbl(c,k){if(k==='installed')return revStage(c)||'Revenue stage';if(k.startsWith('st:'))return k.slice(3);return MET[k][0]}
const statusBdg=s=>({running:bdg('<span class="dot"></span>Running','good'),scheduled:bdg('Scheduled','blue'),paused:bdg('Paused','warn'),draft:bdg('Draft'),ended:bdg('Ended')})[s]||bdg(s);
