M.tileMetrics=m=>{const c=camp(m.id);const opts=Object.keys(MET).map(k=>[k,metLbl(c,k)]).concat(stagesOf(c).map(s=>['st:'+s.n,'Stage: '+s.n]));return MS('Choose the numbers to show',`<p class="muted small">Pick up to ${m.where==='row'?7:4}. You can swap any number for any stage.</p><div class="choice">${opts.map(([k,l])=>`<button class="${m.sel.includes(k)?'on':''}" data-act="tmPick" data-k="${esc(k)}">${esc(l)}</button>`).join('')}</div>`,`${btn('Cancel','close',{k:'ghost'})}${btn('Save','tmSave',{k:'primary'})}`,'n')};
A.tmPick=el=>{const a=S.modal.sel,k=el.dataset.k,i=a.indexOf(k),max=S.modal.where==='row'?7:4;if(i>=0)a.splice(i,1);else{if(a.length>=max)a.shift();a.push(k)}renderModal()};
A.tmSave=()=>{const c=camp(S.modal.id);if(S.modal.where==='row')c.rowMetrics=S.modal.sel.slice();else c.metrics=S.modal.sel.slice();closeM();rr();toast('Numbers updated')};
A.campStatus=el=>{hidePop();const c=camp(el.dataset.id);c.status=el.dataset.s;if(c.status==='running'&&/Starts|Draft/.test(c.started))c.started='Sep 27';rr();toast(c.status==='paused'?c.name+' paused — open conversations continue, no new ones start':c.name+' is live')};
A.campDup=el=>{hidePop();const c=clone(camp(el.dataset.id));c.id='k'+uid('');c.name+=' (copy)';c.status='draft';c.started='Draft';['reached','replied','interested','booked','installed','revenue','cost'].forEach(k=>c[k]=0);D.campaigns.unshift(c);D.products[c.id]=clone(D.products[el.dataset.id]||D.products.k1);rr();toast('Duplicated as a draft')};

