 booking:false,qual:clone(D.agents[0].job.qual),disq:clone(D.agents[0].job.disq),script:'',dos:['Say the price in the first message','Offer free installation this month','Confirm the address back'],donts:['Don’t call before 9 AM or after 8 PM','Don’t discuss competitors’ prices','Don’t promise installation dates not on the calendar'],kb:clone(D.agents[0].kb.slice(0,1)),
