 <div class="card">${L.map(s=>`<div class="lr"><span class="stg" style="height:24px"><i style="background:${s.c}"></i>${ic(s.i,12)}${esc(s.n)}</span><span class="m small muted trunc">${s.crit.length} criteria · “${esc(s.crit[0]||'')}”</span>${s.rev?bdg(ic('dollar',11)+'Revenue','good'):''}${s.t==='lost'?bdg('Lost'):s.t==='pending'?bdg('Pending','warn'):''}${iconBtn('edit','stageEdit','Edit stage',`data-pipe="${w.pipe}" data-dir="${d}" data-id="${s.id}"`,'xs')}</div>`).join('')}</div>
