 <div class="grid g3">${L.map(a=>{const on=w.agents.includes(a.id);return `<button class="atile ${on?'on':''}" data-act="wzAg" data-id="${a.id}"><div class="row nw"><span class="av bot lg">${ic(AT[a.type].i,18)}</span><div class="grow"><b>${a.name}</b><div class="small muted">${esc(a.voice)}</div></div><span class="pick ${on?'on':''}" style="padding:0;border:0;width:auto;background:none"><span class="cbx">${on?ic('check',11):''}</span></span></div><div class="mt">${AT[a.type].m.map(([k,l,u])=>`<div><b>${u==='$'?money(a.ws[k]):nf(a.ws[k])+(u==='%'?'%':'')}</b><span>${l}</span></div>`).join('')}</div><div class="gscore">${ic('globe',12)} Global: ${a.global.success}% success · ${a.global.conv}% conversion</div></button>`}).join('')}</div>
