/* follow-up builder (shared with agents) */
function fuObj(ctx){return ctx==='wz'?S.wz.fu:ctx==='st'?D.stFollow:agent(S.ag.sel).follow}
function fuHTML(ctx,note){const fu=fuObj(ctx),d=S.fuDir[ctx];const who=ctx==='wz'?S.wz.agents:D.agents.map(a=>a.id);if(ctx==='st'){}
 return `<div class="banner ai">${sw(fu.ai,'fuAI',`data-ctx="${ctx}"`)}<div class="grow"><b>Let AI handle this</b> <span class="bdg ai">Recommended</span><div class="small muted">AI picks the best timing and channel for each person and stops when they reply.</div></div></div>
 ${note?`<div class="note">${note}</div>`:''}
 <div style="${fu.ai?'opacity:.55;pointer-events:none':''}" class="stack-s"><div class="row between">${seg([['out','Outbound follow-ups','out'],['in','Inbound follow-ups','in']],d,'fuDir',`data-ctx="${ctx}"`)}${btn('Copy to '+(d==='out'?'inbound':'outbound'),'fuCopy',{k:'xs',i:'copy',a:`data-ctx="${ctx}"`})}</div>
 ${fu[d].map((s,i)=>`<div class="banner" style="padding:8px 10px;gap:6px;font-size:13px"><span class="bdg">${i+1}</span>If ${sel(FU_IF,s.if,`data-chg="fuSet" data-ctx="${ctx}" data-i="${i}" data-k="if"`,'sm auto')} after ${sel(FU_AFTER,s.after,`data-chg="fuSet" data-ctx="${ctx}" data-i="${i}" data-k="after"`,'sm auto')} → ${sel(FU_THEN,s.then,`data-chg="fuSet" data-ctx="${ctx}" data-i="${i}" data-k="then"`,'sm auto')} by ${sel(who.map(a=>[a,agName(a)]),s.by,`data-chg="fuSet" data-ctx="${ctx}" data-i="${i}" data-k="by"`,'sm auto')} using ${sel(FU_TPL,s.tpl,`data-chg="fuSet" data-ctx="${ctx}" data-i="${i}" data-k="tpl"`,'sm auto')}<span class="grow"></span>${iconBtn('trash','fuRm','Remove step',`data-ctx="${ctx}" data-i="${i}"`,'xs')}</div>`).join('')}
 <div class="row">${btn('Add a step','fuAdd',{k:'sm',i:'plus',a:`data-ctx="${ctx}"`})}</div>
 <div class="banner" style="font-size:13px">${sw(fu.drop.on,'fuDrop',`data-ctx="${ctx}"`)}<b>Drop the lead</b> and stop following up after ${sel(['2','3','4','5','6','8'],String(fu.drop.n),`data-chg="fuDropN" data-ctx="${ctx}"`,'sm auto')} tries with ${sel(['no reply','no answer','no reply or answer'],fu.drop.cond,`data-chg="fuDropC" data-ctx="${ctx}"`,'sm auto')}</div></div>`}
const fuR=()=>{if(S.modal&&S.modal.t==='agFollow')renderModal();else rr()};
